86	        const TopoInfoWithNetLayerDetails* topoInfo, const OpParam& opParam,
87	        const std::map<HcclCMDType, std::vector<HcclAlgoType>>& configAlgMap, std::string& selectAlgName) const;
88	    virtual SelectorStatus SelectAicpuAlgo(
89	        const TopoInfoWithNetLayerDetails* topoInfo, const OpParam& opParam,
90	        const std::map<HcclCMDType, std::vector<HcclAlgoType>>& configAlgMap, std::string& selectAlgName) const;
91	    virtual SelectorStatus SelectAivAlgo(
92	        const TopoInfoWithNetLayerDetails* topoInfo, const OpParam& opParam,
93	        const std::map<HcclCMDType, std::vector<HcclAlgoType>>& configAlgMap, std::string& selectAlgName) const;
94	    virtual SelectorStatus SelectDPUAlgo(
95	        const TopoInfoWithNetLayerDetails* topoInfo, const OpParam& opParam,
96	        const std::map<HcclCMDType, std::vector<HcclAlgoType>>& configAlgMap, std::string& selectAlgName) const;
97	    bool IsStarsState(const OpExecuteConfig& opExecuteConfig) const;
98	    bool IsRollBackAiv(OpParam& opParam, TopoInfoWithNetLayerDetails* topoInfo) const;
