130	#define HCCL_AIV_NOT_MATCH_LOG(opParam, BASE_LOG, fmt, ...)                                                 \
131	    do {                                                                                                    \
132	        BASE_LOG(fmt, ##__VA_ARGS__);                                                                       \
133	        if ((opParam).opExecuteConfig == OpExecuteConfig::AIV_ONLY) {                                       \
134	            HCCL_ERROR("Failed to select AIV algorithm while configured as AIV_ONLY. " fmt, ##__VA_ARGS__); \
135	        }                                                                                                   \
136	    } while (0)
