19	HcclResult
20	ExecuteSelector::Run(OpParam& opParam, TopoInfoWithNetLayerDetails* topoInfo, std::string& selectAlgName) const
21	{
22	    HCCL_DEBUG("[Algo][Selector] Run.");
23	    std::map<u32, AutoSelectorBase*> selectors = SelectorRegistry::Global()->GetAllSelectors();
24	
25	    if (opParam.isMc2) {
26	        auto iter = selectors.find(18);
27	        if (iter == selectors.end()) {
28	            HCCL_ERROR("[Algo][Selector] CCU selector is not registried.");
29	            return HcclResult::HCCL_E_NOT_SUPPORT;
30	        }
31	        if (iter->second->Select(opParam, topoInfo, selectAlgName) == SelectorStatus::MATCH) {
32	            HCCL_INFO(
33	                "[Algo][Selector] The ccu selector[priority of %u] is matched, the selected algo type is %s",
34	                iter->first, selectAlgName.c_str());
35	            return HcclResult::HCCL_SUCCESS;
36	        }
37	        HCCL_ERROR("[Algo][Selector] CCU selector can not match for optype[%d].", opParam.opType);
38	        return HcclResult::HCCL_E_NOT_SUPPORT;
39	    }
40	
41	    selectors = SelectorRegistry::Global()->GetSelectorsByOpType(opParam.opType);
42	    HCCL_INFO("[Algo][Selector] The selector nums of optype[%d] is [%zu].", opParam.opType, selectors.size());
43	    for (auto iter : selectors) {
44	        HCCL_DEBUG("[Algo][Selector] The selector[priority of %llu] is running.", iter.first);
45	        if (iter.second->Select(opParam, topoInfo, selectAlgName) == SelectorStatus::MATCH) {
46	            HCCL_INFO(
47	                "[Algo][Selector] The selector[priority of %llu] is matched, the selected algo type is %s", iter.first,
48	                selectAlgName.c_str());
49	            return HcclResult::HCCL_SUCCESS;
50	        }
51	    }
52	
53	    HCCL_ERROR("[Algo][Selector] No selector is matched.");
54	    return HcclResult::HCCL_E_NOT_SUPPORT;
55	}
