70	bool AutoSelectorBase::IsRollBackAiv(OpParam& opParam, TopoInfoWithNetLayerDetails* topoInfo) const
71	{
72	    bool isAllToAllOps = opParam.opType == HcclCMDType::HCCL_CMD_ALLTOALL
73	                         || opParam.opType == HcclCMDType::HCCL_CMD_ALLTOALLV
74	                         || opParam.opType == HcclCMDType::HCCL_CMD_ALLTOALLVC;
75	    bool isInt64ReduceOps = opParam.DataDes.dataType == HcclDataType::HCCL_DATA_TYPE_INT64
76	                            && (opParam.opType == HcclCMDType::HCCL_CMD_ALLREDUCE
77	                                || opParam.opType == HcclCMDType::HCCL_CMD_REDUCE_SCATTER
78	                                || opParam.opType == HcclCMDType::HCCL_CMD_REDUCE);
79	    return topoInfo->level0PcieMix && topoInfo->level0BigClosRange && (isAllToAllOps || isInt64ReduceOps);
